package dk.sdu.cbse.springlab;import org.springframework.context.annotation.*;import org.springframework.stereotype.Component;import java.util.*;public class Main{public interface IGamePluginService{String name();void start();}public interface IEntityProcessingService{String name();void process();}@Component static class PlayerPlugin implements IGamePluginService,IEntityProcessingService{public String name(){return"Player";}public void start(){System.out.println("Start Player");}public void process(){System.out.println("Process Player");}}@Component static class AsteroidPlugin implements IGamePluginService,IEntityProcessingService{public String name(){return"Asteroids";}public void start(){System.out.println("Start Asteroids");}public void process(){System.out.println("Process Asteroids");}}@Component static class Game{private final List<IGamePluginService> plugins;private final List<IEntityProcessingService> processors;Game(List<IGamePluginService> p,List<IEntityProcessingService> e){plugins=p;processors=e;}void run(){plugins.forEach(IGamePluginService::start);processors.forEach(IEntityProcessingService::process);}}@Configuration @ComponentScan(basePackageClasses=Main.class)static class Config{}public static void main(String[]a){try(var c=new AnnotationConfigApplicationContext(Config.class)){c.getBean(Game.class).run();}}}